<?php http_response_code(404); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>404 — JXHQ</title><script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script><link rel="stylesheet" href="/assets/site.css"></head><body><main class="mx-auto grid min-h-screen max-w-3xl place-items-center px-5 py-10"><div class="w-full"><section class="border border-[#d6d2ca] bg-white p-8 sm:p-12"><p class="font-mono text-sm text-[#ff3b3b]">HTTP 404</p><h1 class="mt-4 text-5xl font-black tracking-[-.05em]">Nothing here.</h1><p class="mt-5 text-[#686d6d]">The server exists. This page apparently had other plans.</p><div class="mt-8 flex flex-wrap gap-3"><a class="bg-[#111313] px-5 py-3 font-black text-white" href="/">Back to JXHQ →</a><button id="terminal-trigger" class="border border-[#cfcac1] px-5 py-3 font-mono text-xs text-[#777c7c]" title="This button definitely does nothing">_</button></div></section><section id="secret-terminal" class="mt-5 hidden overflow-hidden border border-[#343838] bg-[#111313] text-[#e9e7e1]"><div class="flex items-center justify-between border-b border-white/10 px-4 py-3 text-xs"><span class="font-bold">jxhq recovery console</span><button id="terminal-close" aria-label="Close terminal">×</button></div><div id="terminal-output" class="h-56 overflow-auto p-4 font-mono text-xs leading-relaxed"><p class="text-[#ff5b5b]">Connection established.</p><p>Type <strong>help</strong>. Pretend this is very secure.</p></div><form id="terminal-form" class="flex border-t border-white/10"><label class="px-4 py-3 font-mono text-xs text-[#ff5b5b]" for="terminal-input">visitor@jxhq:~$</label><input id="terminal-input" class="min-w-0 flex-1 bg-transparent py-3 pr-4 font-mono text-xs text-white outline-none" autocomplete="off" spellcheck="false"></form></section></div></main><script src="/assets/site.js" defer></script><script>
const trigger=document.getElementById('terminal-trigger'),terminal=document.getElementById('secret-terminal'),input=document.getElementById('terminal-input'),output=document.getElementById('terminal-output');
function openTerminal(){terminal.classList.remove('hidden');input.focus()}trigger.onclick=openTerminal;document.getElementById('terminal-close').onclick=()=>terminal.classList.add('hidden');
let typed='';document.addEventListener('keydown',e=>{if(!terminal.classList.contains('hidden'))return;typed=(typed+e.key.toLowerCase()).slice(-8);if(typed.endsWith('terminal'))openTerminal()});
const commands={help:'Commands: help, whoami, status, coffee, home, clear, exit',whoami:'A curious human in the wrong directory.',status:'All systems operational. This URL is still missing.',coffee:'Coffee subsystem: nominally caffeinated. /coffee has the serious report.',home:'Opening / ...',exit:'Closing connection.'};
document.getElementById('terminal-form').onsubmit=e=>{e.preventDefault();const command=input.value.trim().toLowerCase();output.insertAdjacentHTML('beforeend','<p><span class="text-[#ff5b5b]">visitor@jxhq:~$</span> '+command.replace(/[<>&]/g,'')+'</p>');if(command==='clear')output.innerHTML='';else{output.insertAdjacentHTML('beforeend','<p class="text-white/65">'+(commands[command]||'Command not found. The terminal is decorative, but your enthusiasm is real.')+'</p>');if(command==='home')setTimeout(()=>location.href='/',500);if(command==='coffee')setTimeout(()=>location.href='/coffee/',800);if(command==='status')setTimeout(()=>location.href='https://status.jxhq.net',800);if(command==='exit')setTimeout(()=>terminal.classList.add('hidden'),400)}input.value='';output.scrollTop=output.scrollHeight};
</script></body></html>
